{"slice":{"slice_id":"s_coefficients","introduces":[{"id":"faux","type":"math","content":"\\ce{Al + O3 -> Al2O3}","style":{"role":"secondary"},"layout":{"next_to":"atomes","direction":"down","gap":"lg"}},{"id":"coef","type":"math","content":"\\ce{2Al + O2 -> Al2O3}","parts":[{"id":"deux","text":"2"},{"id":"alu","text":"\\ce{Al}"}],"layout":{"next_to":"faux","direction":"down","gap":"lg"}}],"beats":[{"id":"piege","say":"On pourrait être tenté de changer l'indice de l'oxygène et d'écrire O trois. Mais ça, c'est une autre molécule : ce n'est plus l'oxygène de l'air.","cues":[{"id":"c_indice","text":"changer l'indice"},{"id":"c_molecule","text":"une autre molécule"}],"do":[{"id":"w_faux","verb":"write","target":"faux","at":"cue:c_indice"},{"id":"h_faux","verb":"highlight","target":"faux","role":"unknown","start":"cue:c_molecule","end":"cue_end:c_molecule"}]},{"id":"coeff","say":"À la place, on ajoute un chiffre devant la formule : un coefficient. Ce deux devant Al veut dire deux atomes d'aluminium.","cues":[{"id":"c_coefficient","text":"un coefficient"},{"id":"c_deuxalu","text":"deux atomes d'aluminium"}],"do":[{"id":"f_faux","verb":"fade_out","target":"faux","at":"cue:c_coefficient"},{"id":"w_deux","verb":"write","target":"coef","part":"deux","at":"cue:c_deuxalu"},{"id":"h_deux","verb":"highlight","target":"coef","part":"deux","role":"accent","start":"cue:c_deuxalu","end":"cue_end:c_deuxalu"}],"pause_after":"normal"}]}}
{"slice":{"slice_id":"s_balancer","introduces":[{"id":"etape_oxy","type":"math","content":"\\ce{4Al + 3O2 -> 2Al2O3}","parts":[{"id":"quatre_al","text":"4Al"},{"id":"trois_o","text":"3O2"},{"id":"deux_al2o3","text":"2Al2O3"}]},{"id":"verif","type":"matrix","params":{"rows":[["4","4"],["6","6"]],"row_labels":["Al (aluminium)","O (oxygène)"],"column_labels":["à gauche","à droite"]},"layout":{"next_to":"etape_oxy","direction":"down","gap":"lg"}}],"beats":[{"id":"oxy","say":"Il manque des oxygènes à gauche : il en faut six. Avec des O deux, trois molécules donnent six oxygènes.","cues":[{"id":"c_six","text":"il en faut six"},{"id":"c_trois_o","text":"trois molécules"}],"do":[{"id":"dim_coef","verb":"dim","target":"coef","at":"cue:c_six"},{"id":"w_o","verb":"write","target":"etape_oxy","part":"trois_o","at":"cue:c_trois_o"}]},{"id":"alu","say":"Ce trois devant O deux change aussi l'aluminium à droite : deux Al deux O trois donnent quatre aluminiums. Il faut donc quatre Al à gauche.","cues":[{"id":"c_quatre","text":"quatre aluminiums"},{"id":"c_quatre_al","text":"quatre Al à gauche"}],"do":[{"id":"w_al2o3","verb":"write","target":"etape_oxy","part":"deux_al2o3","at":"cue:c_quatre"},{"id":"w_quatre","verb":"write","target":"etape_oxy","part":"quatre_al","at":"cue:c_quatre_al"}],"pause_after":"normal"},{"id":"verifie","say":"Vérifions : quatre aluminiums de chaque côté, six oxygènes de chaque côté. L'équation est équilibrée.","cues":[{"id":"c_quatre_deux","text":"quatre aluminiums de chaque côté"},{"id":"c_six_deux","text":"six oxygènes de chaque côté"}],"do":[{"id":"s_verif","verb":"show","target":"verif","at":"cue:c_quatre_deux"},{"id":"h_verif","verb":"highlight","target":"verif","role":"result","start":"cue:c_six_deux","end":"cue_end:c_six_deux"}],"pause_after":"long"}]}}
{"slice":{"slice_id":"s_retenir","introduces":[{"id":"regle","type":"math","content":"\\ce{4Al + 3O2 -> 2Al2O3}","parts":[{"id":"c1","text":"4"},{"id":"c2","text":"3"},{"id":"c3","text":"2"}]},{"id":"idee","type":"text","content":"Les coefficients multiplient les atomes ; les indices sont fixés par la molécule.","layout":{"next_to":"regle","direction":"down","gap":"md"}}],"beats":[{"id":"retenir","say":"À retenir : les coefficients, les chiffres devant les formules, se répartissent les atomes pour que chaque sorte soit égalisée. Les indices, eux, ne bougent jamais.","cues":[{"id":"c_retenir","text":"À retenir"},{"id":"c_coeff","text":"les coefficients"},{"id":"c_indices","text":"Les indices"}],"do":[{"id":"f_brut","verb":"fade_out","target":"brut","at":"beat:start"},{"id":"f_atomes","verb":"fade_out","target":"atomes","at":"beat:start"},{"id":"f_etape","verb":"fade_out","target":"etape_oxy","at":"beat:start"},{"id":"f_verif","verb":"fade_out","target":"verif","at":"beat:start"},{"id":"cadre","verb":"camera.focus","targets":["regle","idee"],"bounds":"layout_bounds","at":"beat:start"},{"id":"h_coeff","verb":"highlight","target":"regle","part":"c1","role":"accent","start":"cue:c_coeff","end":"cue_end:c_coeff"},{"id":"h_ind","verb":"highlight","target":"regle","part":"c2","role":"given","start":"cue:c_indices","end":"cue_end:c_indices"},{"id":"s_idee","verb":"show","target":"idee","at":"after:h_ind"}]}]}}
